// ---------------------------------------------------------------------------
// Configuration and models
// ---------------------------------------------------------------------------

bool ai_trickle_config_save(void) {
    return save_config(EEPROM_AI_TRICKLE_BASE_ADDR, &ai_trickle_data, sizeof(eeprom_ai_trickle_data_t));
}


/*
 * Read a configuration block written by save_config() with the given size.
 * Unlike load_config() it never writes defaults back, so it can be used to
 * probe for an older layout.
 */
static bool read_config_block(void * cfg, size_t size) {
    size_t read_size = size + sizeof(uint32_t);
    uint8_t * buf = malloc(read_size);
    if (!buf) {
        return false;
    }

    bool is_ok = eeprom_read(EEPROM_AI_TRICKLE_BASE_ADDR, buf, read_size);
    if (is_ok) {
        uint16_t rev;
        uint32_t stored_crc32;
        memcpy(&rev, buf, sizeof(rev));
        memcpy(&stored_crc32, buf + size, sizeof(stored_crc32));
        is_ok = rev == 0 && software_crc32(buf, size) == stored_crc32;
    }
    if (is_ok) {
        memcpy(cfg, buf, size);
    }

    free(buf);
    return is_ok;
}


static void reset_speed(uint8_t idx) {
    trickle_speed_reset(&ai_trickle_data.speed[idx], ai_trickle_data.precision_level);
}


bool ai_trickle_init(void) {
    static eeprom_ai_trickle_data_t defaults;

    defaults = default_ai_trickle_data;
    for (int i = 0; i < MAX_PROFILE_CNT; i += 1) {
        trickle_model_reset(&defaults.models[i]);
        trickle_speed_reset(&defaults.speed[i], defaults.precision_level);
    }

    bool is_ok;
    if (read_config_block(&ai_trickle_data, sizeof(eeprom_ai_trickle_data_t))) {
        is_ok = true;
    }
    else if (read_config_block(&ai_trickle_data, AI_TRICKLE_DATA_V1_SIZE)) {
        // Rev 1: keep the learned models, add the new settings. The tolerance
        // used to follow the precision level.
        printf("Migrating AI trickle configuration\n");
        ai_trickle_data.tolerance_gr = trickle_default_tolerance(ai_trickle_data.precision_level);
        ai_trickle_data.auto_speed = 0;
        ai_trickle_data.tap_degrees = 0;
        memset(ai_trickle_data.reserved2, 0x0, sizeof(ai_trickle_data.reserved2));
        if (ai_trickle_data.mode_preset == AI_PRESET_AUTO) {
            // Rev 1 had Custom at this position
            ai_trickle_data.mode_preset = AI_PRESET_CUSTOM;
        }
        for (int i = 0; i < MAX_PROFILE_CNT; i += 1) {
            trickle_speed_reset(&ai_trickle_data.speed[i], ai_trickle_data.precision_level);
        }
        is_ok = save_config(EEPROM_AI_TRICKLE_BASE_ADDR, &ai_trickle_data, sizeof(eeprom_ai_trickle_data_t));
    }
    else {
        // First start (or the pre-CRC rev scheme): load_config writes the defaults
        is_ok = load_config(EEPROM_AI_TRICKLE_BASE_ADDR, &ai_trickle_data, &defaults,
                            sizeof(eeprom_ai_trickle_data_t), EEPROM_AI_TRICKLE_DATA_REV);
    }
    if (!is_ok) {
        printf("Unable to read AI trickle configuration\n");
        return false;
    }

    // Guard against out of range values written by older versions or REST
    for (int i = 0; i < MAX_PROFILE_CNT; i += 1) {
        trickle_model_sanitize(&ai_trickle_data.models[i]);
    }
    if (ai_trickle_data.precision_level > 100) {
        ai_trickle_data.precision_level = 100;
    }
    for (int i = 0; i < MAX_PROFILE_CNT; i += 1) {
        trickle_speed_sanitize(&ai_trickle_data.speed[i]);
    }
    if (!(ai_trickle_data.tolerance_gr >= 0.01f && ai_trickle_data.tolerance_gr <= 0.5f)) {
        ai_trickle_data.tolerance_gr = TRICKLE_DEFAULT_TOLERANCE_GR;
    }
    if (ai_trickle_data.mode_preset > AI_PRESET_CUSTOM) {
        ai_trickle_data.mode_preset = AI_PRESET_CUSTOM;
    }
    ai_trickle_data.auto_speed = ai_trickle_data.auto_speed ? 1 : 0;
    if (ai_trickle_data.tap_degrees > 180) {
        ai_trickle_data.tap_degrees = 0;
    }
    ai_trickle_menu_sync();
    if (ai_trickle_data.learn_throws < 2 || ai_trickle_data.learn_throws > AI_TRICKLE_MAX_LEARN_THROWS) {
        ai_trickle_data.learn_throws = AI_TRICKLE_DEFAULT_LEARN_THROWS;
    }

    eeprom_register_handler(ai_trickle_config_save);

    return true;
}


static uint8_t selected_profile_idx(void) {
    uint16_t idx = profile_data.current_profile_idx;
    return idx < MAX_PROFILE_CNT ? (uint8_t) idx : 0;
}


static trickle_model_t * model_for_profile(uint8_t idx) {
    // A profile that was renamed holds a different powder now
    const char * name = profile_data.profiles[idx].name;
    if (strncmp(ai_trickle_data.model_names[idx], name, PROFILE_NAME_MAX_LEN) != 0) {
        trickle_model_reset(&ai_trickle_data.models[idx]);
        reset_speed(idx);
        strncpy(ai_trickle_data.model_names[idx], name, PROFILE_NAME_MAX_LEN);
    }
    return &ai_trickle_data.models[idx];
}


const trickle_model_t * ai_trickle_selected_model(void) {
    return model_for_profile(selected_profile_idx());
}


// Speed used for the profile: learned per profile in auto mode, set by hand otherwise
static uint8_t speed_for_profile(uint8_t idx) {
    return ai_trickle_data.auto_speed ? ai_trickle_data.speed[idx].speed : ai_trickle_data.precision_level;
}


static void mode_for_profile(uint8_t idx, trickle_mode_params_t * mode) {
    trickle_mode_params(speed_for_profile(idx), ai_trickle_data.tolerance_gr, mode);
}


float ai_trickle_tolerance(void) {
    return ai_trickle_data.tolerance_gr;
}


uint8_t ai_trickle_speed(void) {
    return speed_for_profile(selected_profile_idx());
}


float ai_trickle_tap_degrees(void) {
    return ai_trickle_data.tap_degrees ? ai_trickle_data.tap_degrees : AI_TAP_DEFAULT_DEGREES;
}


float ai_trickle_last_error(void) {
    return last_error_gr;
}


bool ai_trickle_adaptive_active(void) {
    return ai_trickle_data.enable || learn_active;
}


static void history_add(float target, float final, float landing, float time_s, uint8_t topups, uint8_t flags) {
    ai_trickle_history_entry_t * entry = &history[history_seq % AI_TRICKLE_HISTORY_LEN];

    history_seq += 1;
    entry->seq = history_seq;
    entry->target_gr = target;
    entry->final_gr = final;
    entry->landing_gr = landing;
    entry->time_s = time_s;
    entry->profile_idx = throw_profile_idx;
    entry->level = speed_for_profile(throw_profile_idx);
    entry->topups = topups;
    entry->flags = flags;
}


// ---------------------------------------------------------------------------
// Learning session
// ---------------------------------------------------------------------------

void ai_trickle_learn_start(uint8_t throws) {
    if (throws < 2 || throws > AI_TRICKLE_MAX_LEARN_THROWS) {
        throws = ai_trickle_data.learn_throws;
    }

    learn_active = true;
    learn_just_finished = false;
    learn_converged = false;
    learn_done = 0;
    learn_total = throws;
    learn_scored = 0;
    learn_err_sum = 0.0f;
    learn_err_sum2 = 0.0f;
}


void ai_trickle_learn_stop(void) {
    learn_active = false;
}


bool ai_trickle_learn_active(void) {
    return learn_active;
}


bool ai_trickle_learn_just_finished(void) {
    bool finished = learn_just_finished;
    learn_just_finished = false;
    return finished;
}


uint8_t ai_trickle_learn_done(void) {
    return learn_done;
}


uint8_t ai_trickle_learn_total(void) {
    return learn_total;
}


static void learn_session_update(float final_error, bool scored) {
    learn_done += 1;

    if (scored) {
        learn_scored += 1;
        learn_err_sum += final_error;
        learn_err_sum2 += final_error * final_error;
    }

    float tolerance = ai_trickle_tolerance();
    if (learn_scored >= LEARN_MIN_THROWS) {
        float mean = learn_err_sum / learn_scored;
        float var = learn_err_sum2 / learn_scored - mean * mean;
        float sd = var > 0.0f ? sqrtf(var) : 0.0f;
        learn_converged = fabsf(mean) <= 0.5f * tolerance && sd <= tolerance;
    }

    if (learn_converged || learn_done >= learn_total) {
        trickle_model_t * model = &ai_trickle_data.models[throw_profile_idx];
        if (learn_converged) {
            model->flags |= TRICKLE_MODEL_FLAG_CONVERGED;
        }
        learn_active = false;
        learn_just_finished = true;
        ai_trickle_config_save();
    }
}


// ---------------------------------------------------------------------------
// Series and ladder
// ---------------------------------------------------------------------------

static float ladder_target(uint8_t throw_idx) {
    return series_start_gr + series_step_gr * (float) (throw_idx / series_repeats);
}


static bool series_start(bool ladder, uint8_t total, float start_gr, float step_gr, uint8_t repeats) {
    if (total < 1 || total > AI_SERIES_MAX_THROWS || !(start_gr > 0.0f)) {
        return false;
    }
    if (repeats < 1) {
        repeats = 1;
    }
    if (ladder) {
        // The user sets every number, the limits only catch typos
        if (fabsf(step_gr) > AI_LADDER_MAX_STEP_GR || step_gr == 0.0f) {
            return false;
        }
        float last = start_gr + step_gr * (float) ((total - 1) / repeats);
        if (!(last > 0.0f)) {
            return false;
        }
    }

    series_active = true;
    series_ladder = ladder;
    series_just_finished = false;
    series_done = 0;
    series_total = total;
    series_repeats = repeats;
    series_start_gr = start_gr;
    series_step_gr = ladder ? step_gr : 0.0f;
    series_first_seq = history_seq + 1;

    charge_mode_config.target_charge_weight = ladder ? ladder_target(0) : start_gr;
    return true;
}


static void series_after_throw(void) {
    if (!series_active) {
        return;
    }

    series_done += 1;
    if (series_done >= series_total) {
        series_active = false;
        series_just_finished = true;
        return;
    }

    if (series_ladder) {
        // Next rung, picked up by the next charge
        charge_mode_config.target_charge_weight = ladder_target(series_done);
    }
}


bool ai_trickle_series_active(void) {
    return series_active;
}


void ai_trickle_series_stop(void) {
    series_active = false;
}


bool ai_trickle_series_is_ladder(void) {
    return series_ladder;
}


bool ai_trickle_series_just_finished(void) {
    bool finished = series_just_finished;
    series_just_finished = false;
    return finished;
}


uint8_t ai_trickle_series_done(void) {
    return series_done;
}


uint8_t ai_trickle_series_total(void) {
    return series_total;
}


// ---------------------------------------------------------------------------
// Classic (PID) charges: recorded so the model can learn passively
// ---------------------------------------------------------------------------

void ai_trickle_classic_begin(void) {
    throw_profile_idx = selected_profile_idx();
    trickle_trace_reset(&trace, 0.0f);
    ctrl_running = false;
}


void ai_trickle_classic_sample(float t, float weight_gr, float coarse_rps, float fine_rps) {
    trickle_trace_add(&trace, t, weight_gr, coarse_rps, fine_rps);
}


void ai_trickle_classic_coarse_stop(float t) {
    trickle_trace_mark_coarse_stop(&trace, t);
}


void ai_trickle_classic_end(float target_gr, float settled_gr, float charge_time_s) {
    uint8_t flags = 0;

    if (ai_trickle_data.auto_learn) {
        trickle_model_t * model = model_for_profile(throw_profile_idx);
        trickle_fit_t fit;
        if (trickle_fit_trace(&trace, model, &fit)) {
            trickle_throw_result_t result = {
                .target_gr = target_gr,
                .landing_weight_gr = NAN,
                .final_weight_gr = settled_gr,
                .charge_time_s = charge_time_s,
                .adaptive = false,
                .aim_below_gr = 0.0f,
            };
            trickle_model_learn(model, &fit, &result, CONTINUOUS_GAIN);
            flags |= AI_THROW_FLAG_MODEL_UPDATED;
            ai_trickle_config_save();
        }
    }

    if (series_active) {
        flags |= AI_THROW_FLAG_SERIES;
    }

    last_error_gr = settled_gr - target_gr;
    last_adaptive = false;
    history_add(target_gr, settled_gr, NAN, charge_time_s, 0, flags);
    series_after_throw();
}


// ---------------------------------------------------------------------------
// Adaptive charges
// ---------------------------------------------------------------------------

void ai_trickle_adaptive_begin(float target_gr, const trickle_motor_limits_t * limits, float current_weight_gr) {
    throw_profile_idx = selected_profile_idx();
    trickle_model_t * model = model_for_profile(throw_profile_idx);

    trickle_mode_params_t mode;
    mode_for_profile(throw_profile_idx, &mode);

    if (isnan(current_weight_gr) || isinf(current_weight_gr)) {
        current_weight_gr = 0.0f;
    }

    ctrl_limits = *limits;
    trickle_ctrl_init(&ctrl, target_gr, model, &mode, &ctrl_limits, 0.0f, current_weight_gr);
    trickle_trace_reset(&trace, 0.0f);

    // Probe pulses on the first throw of a learning session, and whenever the
    // profile has no model yet
    throw_probe = (learn_active && learn_done == 0) || !trickle_model_is_ready(model);
    if (throw_probe) {
        trickle_ctrl_start_probe(&ctrl, 0.0f);
    }

    ctrl_running = true;
}


trickle_phase_t ai_trickle_adaptive_step(float t, float weight_gr, float * coarse_rps, float * fine_rps,
                                         uint32_t * events) {
    trickle_phase_t phase = trickle_ctrl_step(&ctrl, t, weight_gr, coarse_rps, fine_rps);
    *events = ctrl.events;

    if (ctrl.events & TRICKLE_EVENT_COARSE_STOPPED) {
        trickle_trace_mark_coarse_stop(&trace, t);
    }
    trickle_trace_add(&trace, t, weight_gr, *coarse_rps, *fine_rps);

    if (ctrl.events & TRICKLE_EVENT_PROBE_DONE) {
        // Learn from the probe pulses before charging the rest of the throw
        trickle_model_t * model = &ai_trickle_data.models[throw_profile_idx];
        trickle_fit_t fit;
        if (trickle_fit_trace(&trace, model, &fit)) {
            trickle_model_learn(model, &fit, NULL, 1.0f);
            trickle_ctrl_update_model(&ctrl, model);
        }
    }

    return phase;
}


void ai_trickle_adaptive_resume(float t, float current_weight_gr) {
    trickle_mode_params_t mode;
    mode_for_profile(throw_profile_idx, &mode);

    // Keep the trace, restart the controller from the current weight
    trickle_ctrl_init(&ctrl, ctrl.target_gr, &ai_trickle_data.models[throw_profile_idx], &mode, &ctrl_limits,
                      t, current_weight_gr);
    ctrl_running = true;
}


void ai_trickle_adaptive_end(float charge_time_s) {
    ctrl_running = false;

    trickle_model_t * model = &ai_trickle_data.models[throw_profile_idx];
    trickle_throw_result_t result;
    trickle_ctrl_get_result(&ctrl, charge_time_s, &result);

    uint8_t flags = AI_THROW_FLAG_ADAPTIVE;
    if (throw_probe) {
        flags |= AI_THROW_FLAG_PROBE;
    }
    if (learn_active) {
        flags |= AI_THROW_FLAG_LEARN;
    }

    bool done = ctrl.phase == TRICKLE_PHASE_DONE;
    if (!done) {
        flags |= AI_THROW_FLAG_FAULT;
    }
    if (series_active) {
        flags |= AI_THROW_FLAG_SERIES;
    }

    float gain = learn_active ? LEARN_GAIN : (ai_trickle_data.auto_learn ? CONTINUOUS_GAIN : 0.0f);
    if (done && gain > 0.0f) {
        trickle_fit_t fit;
        bool fit_ok = trickle_fit_trace(&trace, model, &fit);
        trickle_model_learn(model, fit_ok ? &fit : NULL, &result, gain);
        flags |= AI_THROW_FLAG_MODEL_UPDATED;
        ai_trickle_config_save();
    }

    float final = done ? result.final_weight_gr : ctrl.last_weight_gr;
    last_error_gr = final - result.target_gr;
    last_adaptive = true;
    history_add(result.target_gr, final, result.landing_weight_gr, charge_time_s, ctrl.topup_count, flags);

    // Learning and probe throws run their own schedule, they say nothing
    // about the speed
    if (ai_trickle_data.auto_speed && done && !learn_active && !throw_probe) {
        bool over_charge = last_error_gr > ai_trickle_data.tolerance_gr + 0.001f;
        if (trickle_speed_update(&ai_trickle_data.speed[throw_profile_idx], over_charge, ctrl.topup_count,
                                 charge_time_s)) {
            ai_trickle_config_save();
        }
    }

    if (learn_active && done) {
        // The probe throw carries extra powder from the pulses, do not score it
        learn_session_update(last_error_gr, !throw_probe);
    }
    if (done) {
        series_after_throw();
    }
}


const char * ai_trickle_phase_name(trickle_phase_t phase) {
    switch (phase) {
        case TRICKLE_PHASE_COARSE:
            return "Coarse";
        case TRICKLE_PHASE_FINE:
            return "Fine";
        case TRICKLE_PHASE_SETTLE:
            return "Settle";
        case TRICKLE_PHASE_TOPUP:
            return "Top up";
        case TRICKLE_PHASE_DONE:
            return "Done";
        case TRICKLE_PHASE_FAULT_NO_FLOW:
            return "No flow";
        case TRICKLE_PHASE_FAULT_TIMEOUT:
            return "Timeout";
        case TRICKLE_PHASE_PROBE:
            return "Probe";
        default:
            return "?";
    }
}


// ---------------------------------------------------------------------------
// Display menu
// ---------------------------------------------------------------------------

uint8_t ai_trickle_menu_apply_preset(void) {
    switch (ai_trickle_data.mode_preset) {
        case AI_PRESET_PRECISION:
            ai_trickle_data.precision_level = TRICKLE_LEVEL_PRECISION;
            ai_trickle_data.auto_speed = 0;
            break;
        case AI_PRESET_BALANCED:
            ai_trickle_data.precision_level = TRICKLE_LEVEL_BALANCED;
            ai_trickle_data.auto_speed = 0;
            break;
        case AI_PRESET_SPEED:
            ai_trickle_data.precision_level = TRICKLE_LEVEL_SPEED;
            ai_trickle_data.auto_speed = 0;
            break;
        case AI_PRESET_AUTO:
            ai_trickle_data.auto_speed = 1;
            break;
        default:
            // Custom: keep the speed set from the web page
            ai_trickle_data.auto_speed = 0;
            break;
    }

    if (ai_tolerance_choice < AI_TOLERANCE_CHOICE_COUNT) {
        ai_trickle_data.tolerance_gr = tolerance_choices[ai_tolerance_choice] * 0.01f;
    }

    ai_trickle_config_save();
    ai_trickle_menu_sync();
    return 70;  // AI Trickle menu
}


// Show the current settings in the display menu after they changed elsewhere
void ai_trickle_menu_sync(void) {
    if (ai_trickle_data.auto_speed) {
        ai_trickle_data.mode_preset = AI_PRESET_AUTO;
    }
    else if (ai_trickle_data.precision_level == TRICKLE_LEVEL_PRECISION) {
        ai_trickle_data.mode_preset = AI_PRESET_PRECISION;
    }
    else if (ai_trickle_data.precision_level == TRICKLE_LEVEL_BALANCED) {
        ai_trickle_data.mode_preset = AI_PRESET_BALANCED;
    }
    else if (ai_trickle_data.precision_level == TRICKLE_LEVEL_SPEED) {
        ai_trickle_data.mode_preset = AI_PRESET_SPEED;
    }
    else {
        ai_trickle_data.mode_preset = AI_PRESET_CUSTOM;
    }

    // Closest menu choice to the tolerance
    float best = 1e9f;
    for (uint8_t i = 0; i < AI_TOLERANCE_CHOICE_COUNT; i += 1) {
        float d = fabsf(tolerance_choices[i] * 0.01f - ai_trickle_data.tolerance_gr);
        if (d < best) {
            best = d;
            ai_tolerance_choice = i;
        }
    }
}


void ai_trickle_profile_reset(uint8_t idx) {
    if (idx >= MAX_PROFILE_CNT) {
        return;
    }
    trickle_model_reset(&ai_trickle_data.models[idx]);
    reset_speed(idx);
    strncpy(ai_trickle_data.model_names[idx], profile_data.profiles[idx].name, PROFILE_NAME_MAX_LEN);
}


uint8_t ai_trickle_menu_reset_model(void) {
    ai_trickle_profile_reset(selected_profile_idx());
    ai_trickle_config_save();
    return 70;
}


// ---------------------------------------------------------------------------
// REST
// ---------------------------------------------------------------------------

static void rest_set_response(struct fs_file *file, const char * buf) {
    size_t len = strlen(buf);
    file->data = buf;
    file->len = len;
    file->index = len;
    file->flags = FS_FILE_FLAGS_HEADER_INCLUDED;
}


// JSON does not know NAN, write null instead
static int json_float(char * buf, size_t len, float v, int decimals) {
    if (isnan(v) || isinf(v)) {
        return snprintf(buf, len, "null");
    }
    return snprintf(buf, len, "%.*f", decimals, v);
}


bool http_ai_trickle_page(struct fs_file *file, int num_params, char *params[], char *values[]) {
    size_t len = strlen(html_ai_trickle_html);

    file->data = html_ai_trickle_html;
    file->len = len;
    file->index = len;
    file->flags = FS_FILE_FLAGS_HEADER_INCLUDED | FS_FILE_FLAGS_HEADER_PERSISTENT;

    return true;
}


bool http_rest_ai_config(struct fs_file *file, int num_params, char *params[], char *values[]) {
    // Mappings
    // a0 (bool): enable adaptive controller
    // a1 (int): manual speed, 0 = careful ... 100 = fastest
    // a2 (bool): keep learning during normal charges
    // a3 (int): throws per learning session
    // a4 (bool): tune the speed of each profile automatically
    // a5 (float): tolerance in grain
    // a6 (int): set the automatic speed of the selected profile (restarts its tuning)
    // a7 (int): fine trickler angle per tap in degrees (1-180)
    // ee (bool): save to eeprom
    // Read only
    // tol (float): tolerance (same as a5, kept for older pages)
    // sp (int): speed used for the selected profile
    // as: automatic speed state of the selected profile [over rate, top ups per charge, mean time, best speed, best time]
    // lim: effective speed limits [coarse min, coarse max, fine min, fine max] (rev/s), profile and motor combined
    // pmx: max speeds set in the profile [coarse, fine], acc: motor ramps [coarse, fine] (rev/s^2)
    // est (float): estimated charge time for the current target and profile
    // pf (int), pn (str): selected profile
    // rd (bool): model of the selected profile is ready
    static char buf[576];
    bool save_to_eeprom = false;
    uint8_t pf = selected_profile_idx();

    for (int idx = 0; idx < num_params; idx += 1) {
        if (strcmp(params[idx], "a0") == 0) {
            ai_trickle_data.enable = string_to_boolean(values[idx]) ? 1 : 0;
        }
        else if (strcmp(params[idx], "a1") == 0) {
            int level = atoi(values[idx]);
            ai_trickle_data.precision_level = (uint8_t) (level < 0 ? 0 : (level > 100 ? 100 : level));
        }
        else if (strcmp(params[idx], "a2") == 0) {
            ai_trickle_data.auto_learn = string_to_boolean(values[idx]) ? 1 : 0;
        }
        else if (strcmp(params[idx], "a3") == 0) {
            int throws = atoi(values[idx]);
            if (throws >= 2 && throws <= AI_TRICKLE_MAX_LEARN_THROWS) {
                ai_trickle_data.learn_throws = (uint8_t) throws;
            }
        }
        else if (strcmp(params[idx], "a4") == 0) {
            ai_trickle_data.auto_speed = string_to_boolean(values[idx]) ? 1 : 0;
        }
        else if (strcmp(params[idx], "a5") == 0) {
            float tolerance = strtof(values[idx], NULL);
            if (tolerance >= 0.01f && tolerance <= 0.5f) {
                ai_trickle_data.tolerance_gr = tolerance;
            }
        }
        else if (strcmp(params[idx], "a7") == 0) {
            int degrees = atoi(values[idx]);
            if (degrees >= 1 && degrees <= 180) {
                ai_trickle_data.tap_degrees = (uint8_t) degrees;
            }
        }
        else if (strcmp(params[idx], "a6") == 0) {
            int speed = atoi(values[idx]);
            trickle_speed_reset(&ai_trickle_data.speed[pf], (uint8_t) (speed < 0 ? 0 : (speed > 100 ? 100 : speed)));
        }
        else if (strcmp(params[idx], "ee") == 0) {
            save_to_eeprom = string_to_boolean(values[idx]);
        }
    }

    ai_trickle_menu_sync();
    if (save_to_eeprom) {
        ai_trickle_config_save();
    }

    const trickle_model_t * model = model_for_profile(pf);
    const trickle_speed_state_t * speed = &ai_trickle_data.speed[pf];
    profile_t * profile = &profile_data.profiles[pf];

    trickle_mode_params_t mode;
    mode_for_profile(pf, &mode);

    // Same limits as a charge: the tighter of profile and motor settings
    trickle_motor_limits_t limits = {
        .coarse_min_rps = fmaxf(get_motor_min_speed(SELECT_COARSE_TRICKLER_MOTOR), profile->coarse_min_flow_speed_rps),
        .coarse_max_rps = fminf(get_motor_max_speed(SELECT_COARSE_TRICKLER_MOTOR), profile->coarse_max_flow_speed_rps),
        .fine_min_rps = fmaxf(get_motor_min_speed(SELECT_FINE_TRICKLER_MOTOR), profile->fine_min_flow_speed_rps),
        .fine_max_rps = fminf(get_motor_max_speed(SELECT_FINE_TRICKLER_MOTOR), profile->fine_max_flow_speed_rps),
        .coarse_accel_rps2 = get_motor_acceleration(SELECT_COARSE_TRICKLER_MOTOR),
        .fine_accel_rps2 = get_motor_acceleration(SELECT_FINE_TRICKLER_MOTOR),
    };
    float target = charge_mode_config.target_charge_weight > 0.0f ? charge_mode_config.target_charge_weight : 40.0f;
    float estimate = trickle_model_is_ready(model) ? trickle_model_estimate_time(model, &mode, &limits, target) : NAN;

    char est_buf[16];
    json_float(est_buf, sizeof(est_buf), estimate, 1);

    snprintf(buf, sizeof(buf),
             "%s"
             "{\"a0\":%s,\"a1\":%d,\"a2\":%s,\"a3\":%d,\"a4\":%s,\"a5\":%.3f,\"a7\":%d,\"tg1\":%.4f,\"tol\":%.3f,\"sp\":%d,"
             "\"as\":[%.3f,%.2f,%.1f,%d,%.1f],\"lim\":[%.3f,%.2f,%.3f,%.2f],\"pmx\":[%.2f,%.2f],\"acc\":[%.1f,%.1f],"
             "\"est\":%s,\"tg\":%.3f,\"pf\":%d,\"pn\":\"%s\",\"rd\":%s}",
             http_json_header,
             boolean_to_string(ai_trickle_data.enable),
             ai_trickle_data.precision_level,
             boolean_to_string(ai_trickle_data.auto_learn),
             ai_trickle_data.learn_throws,
             boolean_to_string(ai_trickle_data.auto_speed),
             ai_trickle_data.tolerance_gr,
             (int) ai_trickle_tap_degrees(),
             trickle_model_is_ready(model) ? model->fine_gpr * ai_trickle_tap_degrees() / 360.0f : 0.0f,
             ai_trickle_data.tolerance_gr,
             speed_for_profile(pf),
             speed->over_rate,
             speed->topup_rate,
             speed->mean_time_s,
             speed->best_speed,
             speed->best_time_s,
             limits.coarse_min_rps,
             limits.coarse_max_rps,
             limits.fine_min_rps,
             limits.fine_max_rps,
             profile->coarse_max_flow_speed_rps,
             profile->fine_max_flow_speed_rps,
             limits.coarse_accel_rps2,
             limits.fine_accel_rps2,
             est_buf,
             target,
             pf,
             profile->name,
             boolean_to_string(trickle_model_is_ready(model)));

    rest_set_response(file, buf);
    return true;
}


bool http_rest_ai_model(struct fs_file *file, int num_params, char *params[], char *values[]) {
    // Mappings (all optional, write when given)
    // pf (int): profile index, defaults to the selected profile
    // kc (float): coarse_gpr, grain per coarse revolution
    // kf (float): fine_gpr, grain per fine revolution
    // lat (float): latency_s
    // tl (float): coarse_tail_gr
    // tsd (float): coarse_tail_sd_gr
    // tau (float): coarse_tail_tau_s
    // cv (float): flow_cv
    // bias (float): stop_bias_gr
    // lsd (float): landing_sd_gr
    // fm, fsd, mt (float), n, fl (int): statistics, count and flags (restore a backup)
    // rst (bool): reset the model
    // ee (bool): save to eeprom
    static char buf[512];

    uint8_t pf = selected_profile_idx();
    for (int idx = 0; idx < num_params; idx += 1) {
        if (strcmp(params[idx], "pf") == 0) {
            int requested = atoi(values[idx]);
            if (requested >= 0 && requested < MAX_PROFILE_CNT) {
                pf = (uint8_t) requested;
            }
        }
    }

    trickle_model_t * model = model_for_profile(pf);
    bool save_to_eeprom = false;
    bool modified = false;

    for (int idx = 0; idx < num_params; idx += 1) {
        float * target = NULL;
        if (strcmp(params[idx], "kc") == 0) {
            target = &model->coarse_gpr;
        }
        else if (strcmp(params[idx], "kf") == 0) {
            target = &model->fine_gpr;
        }
        else if (strcmp(params[idx], "lat") == 0) {
            target = &model->latency_s;
        }
        else if (strcmp(params[idx], "tl") == 0) {
            target = &model->coarse_tail_gr;
        }
        else if (strcmp(params[idx], "tsd") == 0) {
            target = &model->coarse_tail_sd_gr;
        }
        else if (strcmp(params[idx], "tau") == 0) {
            target = &model->coarse_tail_tau_s;
        }
        else if (strcmp(params[idx], "cv") == 0) {
            target = &model->flow_cv;
        }
        else if (strcmp(params[idx], "bias") == 0) {
            target = &model->stop_bias_gr;
        }
        else if (strcmp(params[idx], "lsd") == 0) {
            target = &model->landing_sd_gr;
        }
        else if (strcmp(params[idx], "fm") == 0) {
            target = &model->final_mean_gr;
        }
        else if (strcmp(params[idx], "fsd") == 0) {
            target = &model->final_sd_gr;
        }
        else if (strcmp(params[idx], "mt") == 0) {
            target = &model->mean_time_s;
        }
        else if (strcmp(params[idx], "n") == 0) {
            // Restored from a backup
            model->learned_throws = (uint16_t) strtoul(values[idx], NULL, 10);
            modified = true;
        }
        else if (strcmp(params[idx], "fl") == 0) {
            model->flags = (uint16_t) strtoul(values[idx], NULL, 10);
            modified = true;
        }
        else if (strcmp(params[idx], "rst") == 0 && string_to_boolean(values[idx])) {
            trickle_model_reset(model);
            reset_speed(pf);
            modified = true;
        }
        else if (strcmp(params[idx], "ee") == 0) {
            save_to_eeprom = string_to_boolean(values[idx]);
        }

        if (target != NULL) {
            *target = strtof(values[idx], NULL);
            modified = true;
        }
    }

    if (modified) {
        // Hand tuned values count as a valid model; sanitize keeps them in range
        if (!(model->flags & TRICKLE_MODEL_FLAG_VALID) && model->learned_throws == 0) {
            bool any_param = false;
            for (int idx = 0; idx < num_params; idx += 1) {
                if (strcmp(params[idx], "rst") != 0 && strcmp(params[idx], "ee") != 0 && strcmp(params[idx], "pf") != 0) {
                    any_param = true;
                }
            }
            if (any_param) {
                model->flags |= TRICKLE_MODEL_FLAG_VALID;
                model->learned_throws = 1;
            }
        }
        trickle_model_sanitize(model);
    }

    if (save_to_eeprom) {
        ai_trickle_config_save();
    }

    snprintf(buf, sizeof(buf),
             "%s"
             "{\"pf\":%d,\"pn\":\"%s\",\"kc\":%.4f,\"kf\":%.4f,\"lat\":%.3f,\"tl\":%.3f,\"tsd\":%.3f,\"tau\":%.3f,"
             "\"cv\":%.3f,\"bias\":%.3f,\"lsd\":%.3f,\"fm\":%.3f,\"fsd\":%.3f,\"mt\":%.1f,\"n\":%u,\"fl\":%u}",
             http_json_header,
             pf,
             profile_data.profiles[pf].name,
             model->coarse_gpr,
             model->fine_gpr,
             model->latency_s,
             model->coarse_tail_gr,
             model->coarse_tail_sd_gr,
             model->coarse_tail_tau_s,
             model->flow_cv,
             model->stop_bias_gr,
             model->landing_sd_gr,
             model->final_mean_gr,
             model->final_sd_gr,
             model->mean_time_s,
             model->learned_throws,
             model->flags);

    rest_set_response(file, buf);
    return true;
}


bool http_rest_ai_status(struct fs_file *file, int num_params, char *params[], char *values[]) {
    // Read only
    // cs (int): charge mode state
    // ar (bool): adaptive controller running
    // ph (int): trickle_phase_t of the running/last throw, pn (str) its name
    // pr (float): predicted final weight
    // w (float): current weight, tg (float): target
    // la, ld, lt: learning active, throws done, throws total; lc: converged
    // seq (int): sequence number of the latest throw in the history
    // le (float): error of the last throw
    static char buf[320];
    char pr_buf[16];
    char w_buf[16];
    char le_buf[16];

    json_float(pr_buf, sizeof(pr_buf), ctrl.predicted_gr, 3);
    json_float(w_buf, sizeof(w_buf), ctrl.last_weight_gr, 3);
    json_float(le_buf, sizeof(le_buf), last_error_gr, 3);

    snprintf(buf, sizeof(buf),
             "%s"
             "{\"cs\":%d,\"ar\":%s,\"ph\":%d,\"pn\":\"%s\",\"pr\":%s,\"w\":%s,\"tg\":%.3f,"
             "\"la\":%s,\"ld\":%d,\"lt\":%d,\"lc\":%s,\"seq\":%lu,\"le\":%s,\"lad\":%s,\"tu\":%d}",
             http_json_header,
             (int) charge_mode_config.charge_mode_state,
             boolean_to_string(ctrl_running),
             (int) ctrl.phase,
             ai_trickle_phase_name(ctrl.phase),
             pr_buf,
             w_buf,
             charge_mode_config.target_charge_weight,
             boolean_to_string(learn_active),
             learn_done,
             learn_total,
             boolean_to_string(learn_converged),
             (unsigned long) history_seq,
             le_buf,
             boolean_to_string(last_adaptive),
             ctrl.topup_count);

    rest_set_response(file, buf);
    return true;
}


bool http_rest_ai_history(struct fs_file *file, int num_params, char *params[], char *values[]) {
    // Mappings
    // since (int): only return throws with a larger sequence number
    // Response: {"seq": latest, "h": [[seq, profile, target, final, landing, time, topups, flags, level], ...]}
    static char buf[64 + AI_TRICKLE_HISTORY_LEN * 96];
    uint32_t since = 0;

    for (int idx = 0; idx < num_params; idx += 1) {
        if (strcmp(params[idx], "since") == 0) {
            since = strtoul(values[idx], NULL, 10);
        }
    }

    size_t pos = snprintf(buf, sizeof(buf), "%s{\"seq\":%lu,\"h\":[", http_json_header, (unsigned long) history_seq);

    uint32_t first = history_seq > AI_TRICKLE_HISTORY_LEN ? history_seq - AI_TRICKLE_HISTORY_LEN + 1 : 1;
    if (since + 1 > first) {
        first = since + 1;
    }

    bool comma = false;
    for (uint32_t seq = first; seq <= history_seq && pos < sizeof(buf) - 100; seq += 1) {
        const ai_trickle_history_entry_t * e = &history[(seq - 1) % AI_TRICKLE_HISTORY_LEN];
        char final_buf[16];
        char landing_buf[16];
        json_float(final_buf, sizeof(final_buf), e->final_gr, 3);
        json_float(landing_buf, sizeof(landing_buf), e->landing_gr, 3);

        pos += snprintf(&buf[pos], sizeof(buf) - pos, "%s[%lu,%u,%.3f,%s,%s,%.2f,%u,%u,%u]",
                        comma ? "," : "",
                        (unsigned long) e->seq, e->profile_idx, e->target_gr, final_buf, landing_buf,
                        e->time_s, e->topups, e->flags, e->level);
        comma = true;
    }

    snprintf(&buf[pos], sizeof(buf) - pos, "]}");

    rest_set_response(file, buf);
    return true;
}


bool http_rest_ai_trace(struct fs_file *file, int num_params, char *params[], char *values[]) {
    // Response: weight trace of the current or last throw, at most TRACE_JSON_MAX_POINTS points
    // {"n": samples, "cs": [coarse stop times], "p": [[t, weight, coarse_revs, fine_revs], ...]}
    static char buf[128 + TRACE_JSON_MAX_POINTS * 40];

    size_t pos = snprintf(buf, sizeof(buf), "%s{\"n\":%u,\"cs\":[", http_json_header, trace.count);

    for (uint8_t i = 0; i < trace.coarse_stop_count; i += 1) {
        pos += snprintf(&buf[pos], sizeof(buf) - pos, "%s%.2f", i ? "," : "", trace.coarse_stops[i]);
    }
    pos += snprintf(&buf[pos], sizeof(buf) - pos, "],\"p\":[");

    uint16_t count = trace.count;
    uint16_t step = count / TRACE_JSON_MAX_POINTS + 1;
    bool comma = false;
    for (uint16_t i = 0; i < count && pos < sizeof(buf) - 48; i += step) {
        const trickle_sample_t * s = &trace.samples[i];
        pos += snprintf(&buf[pos], sizeof(buf) - pos, "%s[%.2f,%.3f,%.2f,%.2f]",
                        comma ? "," : "", s->t, s->weight_gr, s->coarse_revs, s->fine_revs);
        comma = true;
    }

    snprintf(&buf[pos], sizeof(buf) - pos, "]}");

    rest_set_response(file, buf);
    return true;
}


bool http_rest_ai_learn(struct fs_file *file, int num_params, char *params[], char *values[]) {
    // Mappings
    // s0 (float): charge weight for the learning session
    // n (int): number of throws
    // go (bool): start a learning session (enters charge mode if needed)
    // stop (bool): end the learning session
    // Response adds err (str): why the session did not start
    static char buf[200];
    bool go = false;
    bool stop = false;
    uint8_t throws = 0;
    float target = NAN;
    const char * error = "";

    for (int idx = 0; idx < num_params; idx += 1) {
        if (strcmp(params[idx], "s0") == 0) {
            target = strtof(values[idx], NULL);
        }
        else if (strcmp(params[idx], "n") == 0) {
            throws = (uint8_t) atoi(values[idx]);
        }
        else if (strcmp(params[idx], "go") == 0) {
            go = string_to_boolean(values[idx]);
        }
        else if (strcmp(params[idx], "stop") == 0) {
            stop = string_to_boolean(values[idx]);
        }
    }

    if (stop) {
        ai_trickle_learn_stop();
    }

    if (go && !profile_is_usable(&profile_data.profiles[selected_profile_idx()])) {
        // Learning with standing motors would only wait for the timeout
        error = "Profile not set up: max speed is 0";
        go = false;
    }

    if (go) {
        if (!isnan(target) && target > 0.0f) {
            charge_mode_config.target_charge_weight = target;
        }
        ai_trickle_learn_start(throws);

        // Enter charge mode the same way the charge mode REST call does
        if (charge_mode_config.charge_mode_state == CHARGE_MODE_EXIT) {
            exit_state = APP_STATE_ENTER_CHARGE_MODE_FROM_REST;
            ButtonEncoderEvent_t button_event = OVERRIDE_FROM_REST;
            xQueueSend(encoder_event_queue, &button_event, portMAX_DELAY);
            charge_mode_config.charge_mode_state = CHARGE_MODE_WAIT_FOR_ZERO;
        }
    }

    snprintf(buf, sizeof(buf),
             "%s{\"la\":%s,\"ld\":%d,\"lt\":%d,\"tg\":%.3f,\"err\":\"%s\"}",
             http_json_header,
             boolean_to_string(learn_active),
             learn_done,
             learn_total,
             charge_mode_config.target_charge_weight,
             error);

    rest_set_response(file, buf);
    return true;
}


bool http_rest_ai_series(struct fs_file *file, int num_params, char *params[], char *values[]) {
    // Mappings
    // go (bool): start, enters charge mode if needed
    // stop (bool): end the series
    // lad (bool): ladder instead of a plain series
    // n (int): number of charges
    // s0 (float): charge weight (series) or first weight (ladder)
    // step (float): ladder step
    // rep (int): charges per ladder rung
    // Response adds: sa (active), sd (done), seq0 (sequence number of the first charge), tg (current target)
    static char buf[256];
    bool go = false;
    bool stop = false;
    bool ladder = false;
    int total = 0;
    int repeats = 1;
    float start = NAN;
    float step = 0.0f;
    const char * error = "";

    for (int idx = 0; idx < num_params; idx += 1) {
        if (strcmp(params[idx], "go") == 0) {
            go = string_to_boolean(values[idx]);
        }
        else if (strcmp(params[idx], "stop") == 0) {
            stop = string_to_boolean(values[idx]);
        }
        else if (strcmp(params[idx], "lad") == 0) {
            ladder = string_to_boolean(values[idx]);
        }
        else if (strcmp(params[idx], "n") == 0) {
            total = atoi(values[idx]);
        }
        else if (strcmp(params[idx], "rep") == 0) {
            repeats = atoi(values[idx]);
        }
        else if (strcmp(params[idx], "s0") == 0) {
            start = strtof(values[idx], NULL);
        }
        else if (strcmp(params[idx], "step") == 0) {
            step = strtof(values[idx], NULL);
        }
    }

    if (stop) {
        series_active = false;
    }

    if (go) {
        if (repeats < 1 || repeats > AI_SERIES_MAX_THROWS ||
            !series_start(ladder, (uint8_t) (total > 0 && total <= AI_SERIES_MAX_THROWS ? total : 0), start, step, (uint8_t) repeats)) {
            error = "Invalid series";
        }
        else if (charge_mode_config.charge_mode_state == CHARGE_MODE_EXIT) {
            exit_state = APP_STATE_ENTER_CHARGE_MODE_FROM_REST;
            ButtonEncoderEvent_t button_event = OVERRIDE_FROM_REST;
            xQueueSend(encoder_event_queue, &button_event, portMAX_DELAY);
            charge_mode_config.charge_mode_state = CHARGE_MODE_WAIT_FOR_ZERO;
        }
    }

    snprintf(buf, sizeof(buf),
             "%s{\"sa\":%s,\"lad\":%s,\"sd\":%d,\"n\":%d,\"s0\":%.3f,\"step\":%.3f,\"rep\":%d,"
             "\"seq0\":%lu,\"tg\":%.3f,\"err\":\"%s\"}",
             http_json_header,
             boolean_to_string(series_active),
             boolean_to_string(series_ladder),
             series_done,
             series_total,
             series_start_gr,
             series_step_gr,
             series_repeats,
             (unsigned long) series_first_seq,
             charge_mode_config.target_charge_weight,
             error);

    rest_set_response(file, buf);
    return true;
}
